import numpy as np
from PIL import Image, ImageDraw
from scipy import ndimage as ndi
from collections import defaultdict
from math import hypot
im=np.asarray(Image.open('/app/target.png').convert('RGB'))
colors={'black':(20,20,24),'red':(208,32,28),'blue':(31,79,200),'yellow':(242,196,12),'green':(27,138,58)}

def skeletonize(mask):
    im=mask.copy().astype(bool)
    h,w=im.shape
    while True:
        changed=False
        for phase in (0,1):
            p=np.pad(im,1)
            p2,p3,p4,p5,p6,p7,p8,p9=(p[0:h,1:w+1],p[0:h,w+2:w+2] if False else p[0:h,2:w+2],p[1:h+1,2:w+2],p[2:h+2,2:w+2],p[2:h+2,1:w+1],p[2:h+2,0:w],p[1:h+1,0:w],p[0:h,0:w])
            # neighbors clockwise N,NE,E,SE,S,SW,W,NW
            ns=[p2,p3,p4,p5,p6,p7,p8,p9]
            B=sum(x.astype(np.uint8) for x in ns)
            A=sum((~ns[i] & ns[(i+1)%8]).astype(np.uint8) for i in range(8))
            c=im & (B>=2)&(B<=6)&(A==1)
            if phase==0: c &= ~(p2&p4&p6) & ~(p4&p6&p8)
            else: c &= ~(p2&p4&p8) & ~(p2&p6&p8)
            if c.any(): im[c]=False; changed=True
        if not changed: break
    return im

def graph_paths(sk):
    ys,xs=np.nonzero(sk); pix=set(zip(ys.tolist(),xs.tolist()))
    nbr={}
    for y,x in pix:
        arr=[]
        for dy in (-1,0,1):
          for dx in (-1,0,1):
            if dy==dx==0: continue
            q=(y+dy,x+dx)
            if q not in pix: continue
            if dy and dx and ((y,x+dx) in pix or (y+dy,x) in pix): continue
            arr.append(q)
        nbr[(y,x)]=arr
    degree={p:len(q) for p,q in nbr.items()}
    vertices={p for p,d in degree.items() if d!=2}
    visited=set(); paths=[]
    def key(a,b): return (a,b) if a<b else (b,a)
    def walk(a,b):
        path=[a,b]; visited.add(key(a,b)); prev,cur=a,b
        while cur not in vertices:
            nxt=[q for q in nbr[cur] if q!=prev and key(cur,q) not in visited]
            if not nxt: break
            q=nxt[0]; visited.add(key(cur,q)); path.append(q); prev,cur=cur,q
        return path
    for v in list(vertices):
        for q in nbr[v]:
            if key(v,q) not in visited: paths.append(walk(v,q))
    # remaining degree-2 cycles
    for a in pix:
        for b in nbr[a]:
            if key(a,b) not in visited:
                paths.append(walk(a,b))
    # prune insignificant one-pixel branches by retaining paths >= 5px or cycles
    out=[]
    for p in paths:
        L=sum(hypot(b[1]-a[1],b[0]-a[0]) for a,b in zip(p,p[1:]))
        if L>=5: out.append((p,L))
    return out,degree

allpaths={}; overlays={}
for name,c in colors.items():
    # classify by closest palette color; include antialias pixels with distance below 150
    d=np.sqrt(((im.astype(float)-np.array(c))**2).sum(axis=2))
    mask=d<145
    # retain close region: target should be pure colors
    # remove isolated noise, fill no gaps
    lab,n=ndi.label(mask,structure=np.ones((3,3)))
    keep=np.zeros_like(mask)
    for i,sz in enumerate(np.bincount(lab.ravel())[1:],1):
        if sz>=4: keep|=(lab==i)
    sk=skeletonize(keep)
    ps,_=graph_paths(sk)
    ps.sort(key=lambda pl:(-pl[1],np.mean(np.array(pl[0])[:,0]),np.mean(np.array(pl[0])[:,1])))
    allpaths[name]=[p for p,L in ps]
    overlays[name]=(keep,sk)
    print(name,'pixels',int(keep.sum()),'skel',int(sk.sum()),'paths',len(ps),'lengths',[(round(L,1),len(p)) for p,L in ps])

# render extracted centerline overlay, colors
out=Image.open('/app/target.png').convert('RGB')
d=ImageDraw.Draw(out)
for name,paths in allpaths.items():
    col=colors[name]
    for p in paths:
        xy=[(x,y) for y,x in p]
        if len(xy)>1:d.line(xy,fill=(0,255,255),width=2)
        else:d.point(xy[0],fill=(0,255,255))
out.save('/app/output/centerlines.png')
np.savez_compressed('/app/output/centerlines.npz',**{k:np.array([np.array(p,dtype=np.int16) for p in v],dtype=object) for k,v in allpaths.items()})
